// Convert public source records into a review list. External text is data only; no LLM or instructions are executed.
const payload = $input.first()?.json ?? {};
const nvdRows = payload.vulnerabilities ?? [];
const kevList = payload.knownExploitedVulnerabilities ?? [];
const kev = new Set(kevList.map(x => x.cveID));
const rows = nvdRows.map(({ cve }) => {
  const id = cve?.id;
  if (!id) return null;
  const metric = cve.metrics?.cvssMetricV40?.[0] ?? cve.metrics?.cvssMetricV31?.[0] ?? cve.metrics?.cvssMetricV30?.[0];
  return {
    id,
    published: cve.published ?? '',
    severity: metric?.cvssData?.baseSeverity ?? 'UNKNOWN',
    score: metric?.cvssData?.baseScore ?? null,
    exploited: kev.has(id),
    description: (cve.descriptions?.find(d => d.lang === 'en')?.value ?? '').slice(0, 1200),
    source: 'NIST NVD',
    url: `https://nvd.nist.gov/vuln/detail/${id}`
  };
}).filter(Boolean);
rows.sort((a, b) => Number(b.exploited) - Number(a.exploited) || Number(b.score ?? 0) - Number(a.score ?? 0));
return rows.slice(0, 40).map(json => ({ json }));

// Keep one candidate per CVE per execution. A persistent datastore is required for durable deduplication across executions.
const seen = new Set();
return $input.all().filter(item => { const id = item.json.id; if (!id || seen.has(id)) return false; seen.add(id); return true; });
